 public static void Run(string mode){if(!Application.isPlaying||!(mode=="p1"||mode=="p3"||mode=="hints"||mode=="echo"))throw new Exception("Fresh Play and p1/p3/hints/echo required");var p=new GameObject("Temporary reconstruction input test").AddComponent<ReconstructionPuzzleProbe>();p.mode=mode;p.output="Docs/VisualEvidence/2026-10-02-Reconstruction/puzzle-"+mode;Directory.CreateDirectory(p.output);p.StartCoroutine(p.Guarded(p.Execute()));}
 IEnumerator Guarded(IEnumerator r){var stack=new Stack<IEnumerator>();stack.Push(r);while(stack.Count>0){object n;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}n=stack.Peek().Current;}catch(Exception e){Finish(false,e.ToString());yield break;}if(n is IEnumerator child)stack.Push(child);else yield return n;}}
 void Check(bool ok,string s){if(!ok)throw new Exception(s);checks.Add(s);}
 IEnumerator Execute(){player=FindFirstObjectByType<FirstPersonController>();input=player.GetComponent<PlayerInput>();interactor=player.GetComponent<PlayerInteractor>();view=player.GetComponentInChildren<Camera>();session=FindFirstObjectByType<GameSession>();campaign=FindFirstObjectByType<CampaignDirector>();loop=FindFirstObjectByType<LoopController>();hints=FindFirstObjectByType<ContextualHints>();first=FindFirstObjectByType<ParallelObservationRelay>();relay=FindFirstObjectByType<RecombinationRelay>(FindObjectsInactive.Include);
 Check(session.IsPaused&&!session.HasStarted,"fresh real title");save=campaign.SuppressSaves;campaign.SuppressSaves=true;Configure();running=true;Status="running";Application.logMessageReceived+=Log;yield return Press(Key.Enter);Check(!session.IsPaused,"Enter starts controls");
 if(mode=="p1")yield return P1();else if(mode=="p3")yield return P3();else if(mode=="hints")yield return Hints();else yield return EchoViews();
 foreach(var pair in takes){Check(pair.take.FrameCount==pair.frames.Length,"take retains count");for(int i=0;i<pair.frames.Length;i++)Check(pair.take[i].Timestamp==pair.frames[i].Timestamp&&pair.take[i].Position==pair.frames[i].Position&&pair.take[i].Rotation==pair.frames[i].Rotation,"immutable frame "+i);}
 Check(error=="","no gameplay runtime errors; editor relay infrastructure logged separately");Finish(true,"");}
 IEnumerator P1(){
 Check(first.RequiresSimultaneousPresence,"new live coincidence mode configured");phase="P1 short plan";yield return RecordP1(.55f);yield return Recall();
 yield return Go(2.5f,-5.3f,0);yield return Go(2.5f,-2,0);yield return Go(3.35f,1.8f,0);yield return Until(()=>loop.ActiveEcho.IsComplete,25,"short Echo never ended");yield return Go(3.35f,10,90);yield return Wait(1);
 Check(first.EchoAAuthorized&&!first.EchoBAuthorized&&!first.IsComplete&&first.MissedWindows>0,"late C cannot use a past B presence; A remains accepted");yield return Capture("01-missed-window");
 yield return Press(Key.H);Check(session.IsPaused,"H after failed plan pauses");float active=hints.ActiveSeconds;yield return Wait(.6f);Check(hints.ActiveSeconds==active,"hint clock excludes help");yield return Press(Key.H);
 phase="P1 retry";yield return Recall();Check(!first.IsComplete&&!first.EchoAAuthorized,"RECALL clears failed-plan latch");yield return RecordP1(6);yield return Recall();
 yield return Go(2.5f,-5.3f,0);yield return Go(2.5f,-2,0);yield return Go(3.35f,1.8f,0);yield return Go(3.35f,10,90);yield return Until(()=>first.IsComplete,20,"replanned P1 did not complete");Check(first.CooperationFraction>=.99f,"live B and present C completed contiguous confirmation");yield return Capture("02-replanned-coincidence");
 yield return Until(()=>loop.ActiveEcho.IsComplete,20,"Echo did not finish");Check(first.IsComplete&&F<SlidingDoor>(first,"gateB").IsOpenRequested,"completed cooperation retains the opening after playback ends");
 }
 IEnumerator RecordP1(float hold){yield return Go(-2.75f,-5.3f,0);yield return Go(-2.75f,3,90);yield return Wait(.75f);Check(first.IsGateAPreviewActive||first.EchoAAuthorized,"A teaching preview responds to actual orientation");yield return Go(-2.75f,11,90);yield return Wait(hold);}
 IEnumerator P3(){
 phase="declared R1 fixture";var hub=FindFirstObjectByType<VS1RecoveryHubGate>();var anchor=FindFirstObjectByType<VS1RecallAnchor>(FindObjectsInactive.Include);
 Check(FindFirstObjectByType<VS1StrongEventOne>().RestoreCompletedLighting(),"initial fixture restores prior lighting");F<GameObject>(hub,"hubRoot").SetActive(true);F<GameObject>(hub,"accessRoot").SetActive(true);F<GameObject>(hub,"domesticResidualRoot").SetActive(true);F<GameObject>(hub,"baselineRoot").SetActive(false);Set(hub,"<IsOpen>k__BackingField",true);player.ResetPose(new Vector3(-5.7f,.03f,27.8f),Quaternion.Euler(0,270,0));fixtures++;yaw=270;pitch=0;yield return Wait(.3f);yield return Use(anchor);Check(anchor.IsActivated&&relay.RequiresPairedTransfer,"actual E fixes R1; paired transfer configured");
 var terminals=FindObjectsByType<TemporalRelayTerminal>(FindObjectsSortMode.None);var a=terminals.Single(t=>!t.FinalReceiver);var b=terminals.Single(t=>t.FinalReceiver);var ga=F<SlidingDoor>(relay,"routeGate");var gb=F<SlidingDoor>(relay,"finalGate");
 phase="P3 missing presence";yield return Go(-5.5f,32.5f,0);yield return Go(-7.8f,32.5f,270);yield return Go(-7.8f,34.2f,0);yield return Aim(a.GetComponent<Collider>().bounds.center);int rejects=relay.RejectedConfirmations;keys=new[]{Key.E};yield return new WaitForSecondsRealtime(.9f);keys=Array.Empty<Key>();yield return Wait(.12f);Check(relay.RejectedConfirmations==rejects+1&&!relay.IsAuthorized&&!ga.IsOpenRequested,"held E without Echo rejects once and cannot open A");yield return Capture("01-no-presence");
 yield return Go(-7.8f,32.5f,180);yield return Go(-5.5f,32.5f,90);
 for(int cycle=0;cycle<2;cycle++){
 phase="P3 record cycle "+cycle;yield return Go(-5.5f,32.5f,0);yield return Go(-5.05f,32.5f,90);yield return Go(-5.05f,35.2f,270);yield return Wait(5.5f);yield return Go(-5.05f,43,270);yield return Wait(6);yield return Recall();Check(!relay.IsAuthorized&&!relay.IsTransferComplete&&ga.IsFullyClosed&&gb.IsFullyClosed,"RECALL resets both secured links");
 phase="P3 receive cycle "+cycle;yield return Go(-5.5f,32.5f,0);yield return Go(-7.8f,32.5f,270);yield return Go(-7.8f,34.2f,0);yield return Until(()=>relay.EchoAtA,20,"A did not reach receiver window");Check(!relay.IsAuthorized&&!ga.IsOpenRequested,"Echo A alone does not press the present terminal");
 if(cycle==0){yield return Press(Key.Escape);Check(session.IsPaused,"Escape pauses separated Echo");float time=loop.ActiveEcho.ElapsedTime;float hintTime=hints.ActiveSeconds;yield return Wait(.6f);Check(loop.ActiveEcho.ElapsedTime==time&&hints.ActiveSeconds==hintTime,"pause freezes Echo and hint clock");yield return Press(Key.Escape);}
 yield return Use(a);Check(relay.IsAuthorized&&ga.IsOpenRequested&&!relay.IsTransferComplete,"A confirmation secures only the first link");yield return Capture("02-A-accepted-"+cycle);yield return Until(()=>ga.IsFullyOpen,5,"A failed to open");yield return Go(-7.8f,39.3f,0);yield return Capture("03-opaque-transfer-"+cycle);yield return Go(-7.8f,42.55f,0);
 if(!relay.EchoAtB){yield return Use(b);Check(!relay.IsTransferComplete,"early B request does not fabricate presence");}
 yield return Until(()=>relay.EchoAtB,15,"B did not reach receiver");yield return Use(b);Check(relay.IsTransferComplete&&relay.CanCrossExit,"present B confirmation secures final opening");yield return Capture("04-B-accepted-"+cycle);yield return Until(()=>loop.ActiveEcho.IsComplete,20,"B playback never finished");Check(ga.IsOpenRequested&&gb.IsOpenRequested&&relay.CanCrossExit,"both committed links survive departure/end of Echo; no race through exit");
 if(cycle==0){yield return Recall();Check(!relay.IsAuthorized&&!relay.IsTransferComplete&&!relay.CanCrossExit,"RECALL clears completed transfer and returns to R1");}
 }
 phase="P3 late crossing";yield return Go(-7.8f,46.35f,0);Check(FindFirstObjectByType<VS1HubReturnGate>().IsOpen,"actual exit crossing remains valid after Echo ended");yield return Capture("05-secured-exit");
 }
 IEnumerator EchoViews(){
 phase="actual adult display recording";yield return Go(-2.75f,-5.3f,0);yield return Go(-2.75f,3,90);yield return Wait(20);yield return Go(-2.75f,11,0);yield return Face(90);yield return Wait(9);yield return Recall();
 phase="adult profile through normal route";yield return Go(-2.75f,.65f,0);yield return Until(()=>loop.ActiveEcho.transform.position.z>2.8f,12,"Echo did not arrive at A");yield return Aim(loop.ActiveEcho.transform.position+Vector3.up*1.17f);yield return Capture("01-profile-full-body");
 yield return Go(-1.36f,3,270);yield return Aim(loop.ActiveEcho.transform.position+Vector3.up*1.64f);Check(Vector3.Distance(view.transform.position,loop.ActiveEcho.transform.position+Vector3.up*1.64f)<1.55f,"near facial view at actual player distance");yield return Capture("02-near-face");
 yield return Go(-2.75f,1.45f,180);yield return Aim(loop.ActiveEcho.transform.position+Vector3.up*1.47f);yield return Capture("03-profile-near");
 yield return Go(-4.2f,3,90);yield return Aim(loop.ActiveEcho.transform.position+Vector3.up*1.45f);yield return Capture("04-rear-silhouette");
 yield return Go(-4.2f,5.8f,0);yield return Until(()=>loop.ActiveEcho.transform.position.z>4.2f,22,"Echo did not start recorded travel");yield return Aim(loop.ActiveEcho.transform.position+Vector3.up*1.18f);yield return Capture("05-moving-original-root");
 Check(loop.ActiveEcho.transform.position.z>4.2f&&!loop.ActiveEcho.IsComplete,"movement image uses a live input-recorded trajectory");Check(loop.ActiveEcho.GetComponentsInChildren<Animator>(true).Length==0&&loop.ActiveEcho.GetComponentsInChildren<AudioSource>(true).Length==0,"display adds no unrecorded articulation or audio");
 }
 IEnumerator Hints(){
 phase="production hint timing and actual retries";Check(F<LoopController>(hints,"loop")==loop,"hints count the actual enabled loop, not preserved inactive prototypes");Check(F<float>(hints,"firstDelay")==45&&F<float>(hints,"nextDelay")==65,"authored production delays are 45/65 seconds");bool old=hints.AutomaticEnabled;hints.AutomaticEnabled=true;float began=hints.ActiveSeconds;yield return Go(-2.75f,-5.0f,0);yield return Recall();yield return Go(-2.75f,-5.0f,0);yield return Recall();Check(loop.CompletedLoopCount==2,"two physical R attempts reached the live loop");
 yield return Until(()=>hints.AutomaticCount==1,28,"real retries failed to accelerate attention");Check(hints.ActiveSeconds-began>=24&&hints.ActiveSeconds-began<29,"attention arrives around 25 active seconds after two retries, earlier than ordinary 45");Check(hints.ManualLevel==0&&hints.IsVisible&&!hints.VisibleText.Contains("Pulsá R"),"first automatic hint orients attention, not explicit steps");yield return Capture("01-attention");
 yield return Press(Key.H);float at=hints.ActiveSeconds,stall=hints.NoProgressSeconds;yield return Wait(2);Check(session.IsPaused&&hints.ActiveSeconds==at&&hints.NoProgressSeconds==stall,"reading help excludes real elapsed seconds");yield return Press(Key.H);
 yield return Go(-2.75f,-5.0f,0);yield return Recall();float relationBegan=hints.ActiveSeconds;yield return Until(()=>hints.AutomaticCount==2,38,"third retry failed to accelerate relationship");Check(hints.ActiveSeconds-relationBegan<38,"relationship arrives within accelerated 35 active seconds, earlier than ordinary 65");Check(!hints.VisibleText.Contains("Pulsá R")&&hints.ManualLevel==1,"automatic escalation gives the relation, never full solution");yield return Capture("02-automatic-relation");
 yield return Press(Key.H);yield return Press(Key.J);Check(hints.ManualLevel==2&&hints.ExplicitRequests==1&&hints.CurrentNote.Contains("Pulsá R"),"deliberate request alone reveals steps");yield return Capture("03-deliberate-steps");yield return Press(Key.H);
 hints.AutomaticEnabled=false;Check(!hints.IsVisible,"off option hides current automatic note");yield return Wait(12);Check(hints.AutomaticCount==2,"disabled hints produce no automatic notices");hints.AutomaticEnabled=true;yield return Wait(12);Check(hints.AutomaticCount==2,"same-stage automatic notes do not repeat after re-enable or manual solution");
 phase="document time";yield return Go(.35f,-5.5f,0);var doc=FindObjectsByType<CampaignStation>(FindObjectsSortMode.None).Single(x=>x.Kind==StationKind.IntroLetter);yield return Use(doc);at=hints.ActiveSeconds;yield return Wait(1);Check(session.IsPaused&&hints.ActiveSeconds==at,"actual document excludes hint clock");yield return Press(Key.Escape);hints.AutomaticEnabled=old;
 }
 IEnumerator Use(Component t){var c=t.GetComponentsInChildren<Collider>().Where(x=>x.enabled&&!x.isTrigger&&x.gameObject.activeInHierarchy).OrderBy(x=>Vector3.Distance(view.transform.position,x.bounds.center)).First();yield return Aim(c.bounds.center);Check(interactor.TryGetTarget(out var target)&&ReferenceEquals(target,t),"real focus reaches "+t.name);yield return Press(Key.E);}
 IEnumerator Recall(){int n=loop.CompletedLoopCount;yield return Press(Key.R);Check(loop.CompletedLoopCount==n+1&&loop.LastRecording!=null,"one real R creates one take");var t=loop.LastRecording;takes.Add((t,Enumerable.Range(0,t.FrameCount).Select(i=>t[i]).ToArray()));}
 IEnumerator Go(float x,float z,float facing){yield return Face(facing,0);float end=Time.realtimeSinceStartup+22;while(Vector2.Distance(new Vector2(player.transform.position.x,player.transform.position.z),new Vector2(x,z))>.10f){if(Time.realtimeSinceStartup>end)throw new Exception("Physical route blocked "+player.transform.position+" -> "+x+","+z);var d=player.transform.InverseTransformDirection(new Vector3(x,player.transform.position.y,z)-player.transform.position);var list=new List<Key>();if(d.x>.055f)list.Add(Key.D);else if(d.x<-.055f)list.Add(Key.A);if(d.z>.055f)list.Add(Key.W);else if(d.z<-.055f)list.Add(Key.S);keys=list.ToArray();yield return null;}yield return Wait(.12f);}
 IEnumerator Aim(Vector3 p){var d=p-view.transform.position;yield return Face(Mathf.Atan2(d.x,d.z)*Mathf.Rad2Deg,-Mathf.Atan2(d.y,new Vector2(d.x,d.z).magnitude)*Mathf.Rad2Deg);}
 IEnumerator Face(float y,float p=0){yaw=y;pitch=p;keys=Array.Empty<Key>();float end=Time.realtimeSinceStartup+5;while(Mathf.Abs(Mathf.DeltaAngle(player.transform.eulerAngles.y,yaw))>.5f||Mathf.Abs(F<float>(player,"pitch")-pitch)>.5f){if(Time.realtimeSinceStartup>end)throw new Exception("Mouse focus/aim failed");yield return null;}yield return Wait(.12f);}
 IEnumerator Press(Key key){keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(.07f);keys=new[]{key};yield return new WaitForSecondsRealtime(.1f);keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(.14f);}
 IEnumerator Wait(float s){keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(s);}
 IEnumerator Until(Func<bool> f,float s,string error){keys=Array.Empty<Key>();float end=Time.realtimeSinceStartup+s;while(!f()){if(Time.realtimeSinceStartup>end)throw new Exception(error);yield return null;}}
 IEnumerator Capture(string n){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(output+"/"+n+"-Game.png",t.EncodeToPNG());Destroy(t);}
 void Configure(){devices=input.devices.ToArray();scheme=input.currentControlScheme;auto=input.neverAutoSwitchControlSchemes;behavior=InputSystem.settings.editorInputBehaviorInPlayMode;sensitivity=F<float>(player,"lookSensitivity");yaw=player.transform.eulerAngles.y;pitch=F<float>(player,"pitch");keyboard=InputSystem.AddDevice<Keyboard>("ReconstructionProbeKeyboard");mouse=InputSystem.AddDevice<Mouse>("ReconstructionProbeMouse");input.neverAutoSwitchControlSchemes=true;input.SwitchCurrentControlScheme("Keyboard&Mouse",keyboard,mouse);InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;configured=true;InputSystem.onBeforeUpdate+=InputUpdate;}
 void InputUpdate(){if(!running||InputState.currentUpdateType!=InputUpdateType.Dynamic)return;InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.QueueStateEvent(mouse,new MouseState{delta=new Vector2(Mathf.Clamp(Mathf.DeltaAngle(player.transform.eulerAngles.y,yaw),-10,10)/sensitivity,Mathf.Clamp(F<float>(player,"pitch")-pitch,-10,10)/sensitivity)});}
 void Log(string m,string s,LogType t){if(t!=LogType.Error&&t!=LogType.Exception&&t!=LogType.Assert)return;if(m.StartsWith("connection.state_change")&&s.Contains("Unity.Relay.Editor.RelayService")){File.AppendAllText(output+"/editor-infrastructure.txt",m+"\n"+s+"\n");return;}error=m;}
 void Finish(bool ok,string message){Status=ok?"PASS":"FAIL";Cleanup();File.WriteAllText(output+"/result.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status=Status,error=message,phase,mode,fixtureCount=fixtures,scope="Input System WASD/mouse/E/R/H/J/Escape. P3 has one initial R1 prerequisite/pose fixture. Hints uses actual RECALL attempts and production 45/65-second defaults; accelerated thresholds are behavior, not fixtures. No direct puzzle/interaction/recall callbacks after fixture. Not human clarity, difficulty, comfort or fear evidence.",takeCount=takes.Count,checks},Newtonsoft.Json.Formatting.Indented));Debug.Log("Reconstruction "+mode+" "+Status+" "+message);}
 void Cleanup(){running=false;InputSystem.onBeforeUpdate-=InputUpdate;Application.logMessageReceived-=Log;if(campaign)campaign.SuppressSaves=save;if(session)session.SetPaused(true);if(!configured)return;configured=false;InputSystem.settings.editorInputBehaviorInPlayMode=behavior;if(input){input.neverAutoSwitchControlSchemes=auto;if(devices.Length>0&&!string.IsNullOrEmpty(scheme))input.SwitchCurrentControlScheme(scheme,devices);}if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(mouse!=null&&mouse.added)InputSystem.RemoveDevice(mouse);}
 void OnDestroy(){Cleanup();}
